//     fait. Le REFUS est maintenant une PRÉ-PASSE exécutée AVANT le premier
//     remove() — aucun nœud touché (§X). Il se lève à la photo près, par un
//     acquittement écrit et imprimé, jamais par tolérance.
//
// CE QUI SUBSISTE DU REPLI, ET POURQUOI CE N'EST PLUS LE MÊME. Le « premier
// paint non réclamé » disparaît EN TANT QUE CHOIX ARBITRAIRE. Ce qui reste est
// un REHÉBERGEMENT d'ordre : une empreinte sans chemin exact prend l'accueil
// libre suivant DANS L'ORDRE DU DOCUMENT. C'est le cas réel du Hero — la photo
// est un fill de RACINE alors que le contrat modélise un enfant Background — et
// sans lui chaque régénération du Hero perdrait la photo du client (c'est le
// cas B de img-paint-preserved-on-amend, mesuré, pas hypothétique). Il est
// déterministe, il préserve l'ordre (donc il ne peut pas produire
// d'interversion), et il est RAPPORTÉ nommément dans rehebergees. Un
// rehébergement vers un accueil dont l'occupant d'origine est ailleurs est, lui,
// une INTERVERSION : il part dans deplacees et rend le rapport ROUGE.
// ==============================================================================

function cheminEnfantDe(chemin, i) { return chemin === '' ? String(i) : chemin + '/' + i; }
function comparerChemins(a, b) {
  const sa = a === '' ? [] : a.split('/').map(Number);
  const sb = b === '' ? [] : b.split('/').map(Number);
  for (let i = 0; i < Math.max(sa.length, sb.length); i++) {
    const x = sa[i] === undefined ? -1 : sa[i];
    const y = sb[i] === undefined ? -1 : sb[i];
    if (x !== y) return x - y;
  }
  return 0;
}
function noeudAuChemin(racine, chemin) {
  if (chemin === '') return racine;
  let n = racine;
  for (const seg of chemin.split('/')) {
    n = (n.children || [])[Number(seg)];
    if (!n) return null;
  }
  return n;
}
function cheminDuNoeud(racine, cible) {
  if (racine === cible) return '';
  const pile = [{ n: racine, c: '' }];
  while (pile.length > 0) {
    const t = pile.shift();
    const kids = t.n.children || [];
    for (let i = 0; i < kids.length; i++) {
      const ch = cheminEnfantDe(t.c, i);
      if (kids[i] === cible) return ch;
      pile.push({ n: kids[i], c: ch });
    }
  }
  return null;
}

// RELEVER — une empreinte, à son emplacement (hostId, cheminPosition).
function harvestImagePaints(node, pool, hostId, chemin) {
  const fills = Array.isArray(node.fills) ? node.fills : [];
  const imgs = fills.filter((f) => f && f.type === 'IMAGE');
  if (imgs.length > 0) {
    pool.push({
      hostId: hostId, cheminPosition: chemin, nomCalque: node.name,
      paints: imgs, claimed: false,
      // Une empreinte illisible est NON VÉRIFIABLE, jamais « identique » :
      // un contrôle empêché n'est pas un contrôle vert (FR-015).
      hashes: imgs.map((f) => (typeof f.imageHash === 'string' && f.imageHash !== '' ? f.imageHash : null)),
    });
  }
  const kids = node.children || [];
  for (let i = 0; i < kids.length; i++) harvestImagePaints(kids[i], pool, hostId, cheminEnfantDe(chemin, i));
}

// Les hôtes d'une reconstruction : le maître, PUIS ses instances de page.
// Deux voies nommées, et la frontière entre elles est écrite ici.
async function hotesDeReconstruction(comp) {
  const hotes = [{ node: comp, hostId: comp.id, hostNom: comp.name, role: 'master' }];
  let voie = 'aucune';
  let raison = null;
  // VOIE ÉPROUVÉE (repli nommé, research D1) : l'orchestrateur a relevé les
  // hôtes avant le lot et les passe par globalThis.__dsc_photos. Forme déjà
  // éprouvée au dépôt — specs/016-canvas-vrai/proofs/repose/photos-instances.json
  // (14 sections, 97 photos). Faiblesse à dire : elle exige un relevé frais
  // avant chaque lot, donc elle ne protège pas une régénération lancée sans
  // l'orchestrateur.
  const reg = (typeof globalThis !== 'undefined' && globalThis.__dsc_photos) || null;
  if (reg && Array.isArray(reg[comp.id])) {
    voie = 'registre-orchestre';
    for (const id of reg[comp.id]) {
      const n = await figma.getNodeByIdAsync(String(id));
      if (n) hotes.push({ node: n, hostId: n.id, hostNom: n.name, role: 'instance' });
    }
  } else if (typeof comp.getInstancesAsync === 'function') {
    // VOIE API — bornée au maître reconstruit, JAMAIS au fichier.
    // ⚠️ NON MESURÉE sur le fichier client au 2026-08-06 : la sonde T005 est
    // consignée empeche (specs/017-photos-honnetes/proofs/sonde-getinstances.md
    // — pont vivant mais saturé, EADDRINUSE sur toute la plage 9223-9232). Le
    // faux-Figma la modélise d'après l'API publiée, ce qui prouve que le moteur
    // emprunte correctement la voie, pas que le fichier client la rende.
    voie = 'getInstancesAsync';
    try {
      for (const inst of (await comp.getInstancesAsync()) || []) {
        hotes.push({ node: inst, hostId: inst.id, hostNom: inst.name, role: 'instance' });
      }
    } catch (e) {
      voie = 'empeche';
      raison = String((e && e.message) || e);
    }
  }
  return { hotes: hotes, voie: voie, raison: raison };
}

function collectImgSpecTargets(spec, out) {
  if (spec.imgPlaceholder === true && !spec.fill) out.push(spec.name);
  for (const ch of spec.children || []) collectImgSpecTargets(ch, out);
}
function findDescendantByName(node, name, dejaVus) {
  if (node.name === name && (!dejaVus || dejaVus.indexOf(node) < 0)) return node;
  for (const ch of node.children || []) {
    const hit = findDescendantByName(ch, name, dejaVus);
    if (hit) return hit;
  }
  return null;
}

// Les accueils, DANS L'ARBRE RECONSTRUIT, rendus par ordre de document.
// Le nom employé ici est celui du CONTRAT, sur un nœud que NOUS venons de bâtir
// — pas le nom d'un calque posé par un designer. §VIII interdit de se fier au
// second pour apparier ; il n'interdit pas de retrouver le nôtre.
function accueilsDuNoeud(rootNode, spec) {
  const noms = [];
  collectImgSpecTargets(spec, noms);
  const vus = [];
  const out = [];
  for (const nom of noms) {
    const n = findDescendantByName(rootNode, nom, vus);
    if (!n) continue;
    vus.push(n);
    out.push({ cheminPosition: cheminDuNoeud(rootNode, n), nom: nom });
  }
  out.sort((a, b) => comparerChemins(a.cheminPosition, b.cheminPosition));
  return out;
}

// Le registre gouverné des levées, baké au script (core/ ne lit aucun fichier).
// Les SEPT champs sont obligatoires et se refusent PAR LE NOM.
function chargerAcquittements() {
  const CHAMPS = ['hostId', 'cheminPosition', 'imageHash', 'motif', 'decidePar', 'decideLe', 'receiptId'];
  const out = [];
  for (let i = 0; i < ACQUITTEMENTS_PHOTOS.length; i++) {
    const e = ACQUITTEMENTS_PHOTOS[i];
    const manquants = CHAMPS.filter((c) => !e || typeof e[c] !== 'string' || e[c] === '');
    if (manquants.length > 0) {
      throw new Error(
        'REFUS au chargement du registre d\'acquittements photo (entrée ' + i + ') : champ(s) manquant(s) ou vide(s) — ' +
        manquants.join(', ') + '. Les sept champs sont obligatoires (hostId, cheminPosition, imageHash, motif, ' +
        'decidePar, decideLe, receiptId) : une porte fail-closed ne se lève pas sur une entrée incomplète.',
      );
    }
    out.push(e);
  }
  return out;
}

// ===== PRÉ-PASSE : RELEVER → COMPTER LES ACCUEILS → DÉCIDER ===================
// Rien de ce qui suit ne mute quoi que ce soit. Le refus, s'il tombe, tombe
// AVANT le premier remove() — c'est tout l'objet de FR-003a et de §X.
async function preparerSauvetagePhotos(comp, specs) {
  const info = await hotesDeReconstruction(comp);
  let accueilsAttendus = 0;
  for (const s of specs) {
    const noms = [];
    collectImgSpecTargets(s, noms);
    if (noms.length > accueilsAttendus) accueilsAttendus = noms.length;
  }
  const acquittes = chargerAcquittements();
  const parHote = [];
  const bloquantes = [];
  const levees = [];
  for (const h of info.hotes) {
    const entrees = [];
    harvestImagePaints(h.node, entrees, h.hostId, '');
    entrees.sort((a, b) => comparerChemins(a.cheminPosition, b.cheminPosition));
    const surplus = entrees.length - accueilsAttendus;
    for (let k = 0; k < surplus; k++) {
      const orpheline = entrees[entrees.length - 1 - k];
      const hash = orpheline.hashes[0];
      const acquit = acquittes.find((a) =>
        a.hostId === orpheline.hostId && a.cheminPosition === orpheline.cheminPosition && a.imageHash === hash);
      if (acquit) levees.push({ imageHash: hash, hostId: orpheline.hostId, cheminPosition: orpheline.cheminPosition, motif: acquit.motif, decidePar: acquit.decidePar, receiptId: acquit.receiptId });
      else bloquantes.push({ imageHash: hash, hostId: orpheline.hostId, cheminPosition: orpheline.cheminPosition, nomCalque: orpheline.nomCalque });
      orpheline.acquittee = !!acquit;
    }
    parHote.push({ hostId: h.hostId, hostNom: h.hostNom, role: h.role, node: h.node, entrees: entrees });
  }
  if (bloquantes.length > 0) {
    throw new Error(
      'REFUS AVANT MUTATION — ' + bloquantes.length + ' photo(s) relevée(s) n\'ont aucun emplacement d\'accueil ' +
      'dans le contrat reconstruit (' + accueilsAttendus + ' accueil(s) par hôte). AUCUN nœud n\'a été touché.\n' +
      bloquantes.map((b) => '  · imageHash=' + b.imageHash + ' hostId=' + b.hostId + ' cheminPosition=' + b.cheminPosition + ' (calque « ' + b.nomCalque + ' », documentaire)').join('\n') +
      '\nCe refus se lève à la photo près, par une entrée écrite dans ' +
      'specs/017-photos-honnetes/registre/acquittements-photos.json (sept champs obligatoires) — jamais par tolérance.',
    );
  }
  return { info: info, parHote: parHote, accueilsAttendus: accueilsAttendus, levees: levees };
}

// ===== REPOSER + RAPPORTER ====================================================
function restaurerPhotos(spec, comp, plan, report, contractId) {
  const accueils = accueilsDuNoeud(comp, spec);
  const hotes = [];
  for (const h of plan.parHote) {
    const libres = accueils.map((a) => a.cheminPosition);
    const pris = {};
    const retrouvees = [];
    const rehebergees = [];
    const deplacees = [];
    const nonReplacees = [];
    const nonVerifiables = [];
    const acquittees = [];
    const dispo = h.entrees.filter((e) => !e.acquittee);
    for (const e of dispo) {
      if (e.hashes.some((x) => x === null)) {
        nonVerifiables.push({ cheminPosition: e.cheminPosition, nomCalque: e.nomCalque, raison: 'imageHash absent — empreinte illisible' });
      }
    }
    // 1. chemin EXACT — le cas normal, la forme de l'arbre n'a pas bougé
    for (const e of dispo) {
      const i = libres.indexOf(e.cheminPosition);
      if (i < 0) continue;
      libres.splice(i, 1);
      pris[e.cheminPosition] = e;
      e.claimed = true;
      retrouvees.push({ cheminPosition: e.cheminPosition, imageHash: e.hashes[0] });
    }
    // 2. le reste, DANS L'ORDRE DU DOCUMENT — bijection déterministe
    for (const e of dispo) {
      if (e.claimed) continue;
      if (libres.length === 0) {
        nonReplacees.push({ cheminPosition: e.cheminPosition, imageHash: e.hashes[0], nomCalque: e.nomCalque });
        continue;
      }
      const vers = libres.shift();
      e.claimed = true;
      pris[vers] = e;
      const mouvement = { de: e.cheminPosition, vers: vers, imageHash: e.hashes[0] };
      // Si l'emplacement d'origine de cette empreinte est occupé par une AUTRE
      // empreinte, ce n'est pas un rehébergement : c'est une INTERVERSION.
      const occupant = dispo.find((o) => o !== e && o.cheminPosition === e.cheminPosition);
      if (occupant) deplacees.push(mouvement); else rehebergees.push(mouvement);
    }
    // 3. appliquer — RÉAFFECTATION du tableau, jamais mutation en place (dans
    //    le vrai Figma node.fills est readonly : une mutation en place est
    //    ignorée en silence).
    let distinctesApres = 0;
    const vusApres = {};
    for (const chemin of Object.keys(pris)) {
      const node = noeudAuChemin(h.node, chemin);
      if (!node) {
        nonReplacees.push({ cheminPosition: chemin, imageHash: pris[chemin].hashes[0], nomCalque: pris[chemin].nomCalque });
        continue;
      }
      node.fills = pris[chemin].paints;
      for (const x of pris[chemin].hashes) if (x && !vusApres[x]) { vusApres[x] = true; distinctesApres++; }
    }
    const vusAvant = {};
    let distinctesAvant = 0;
    for (const e of h.entrees) for (const x of e.hashes) if (x && !vusAvant[x]) { vusAvant[x] = true; distinctesAvant++; }
    for (const l of plan.levees) if (l.hostId === h.hostId) acquittees.push(l);
    hotes.push({
      hostId: h.hostId, hostNom: h.hostNom, role: h.role,
      attendues: h.entrees.length,
      retrouvees: retrouvees.length,
      distinctesAvant: distinctesAvant,
      distinctesApres: distinctesApres,
      deplacees: deplacees,
      rehebergees: rehebergees,
      nonReplacees: nonReplacees,
      nonVerifiables: nonVerifiables,
      acquittees: acquittees,
    });
    // trace héritée, conservée : les consommateurs existants la lisent
    for (const m of retrouvees) { report.preservedImages = report.preservedImages || []; report.preservedImages.push(h.hostId + ':' + m.cheminPosition); }
    for (const m of rehebergees) { report.preservedImages = report.preservedImages || []; report.preservedImages.push(h.hostId + ':' + m.de + ' -> ' + m.vers); }
    for (const m of nonReplacees) { report.unplacedImages = report.unplacedImages || []; report.unplacedImages.push(h.hostId + ':' + m.cheminPosition); }
  }
  // Le verdict, refusable par le nom (data-model §3). Le vert est INTERDIT si
  // une perte, une interversion ou une empreinte illisible existe quelque part.
  let verdict = 'vert';
  if (plan.info.voie === 'empeche') verdict = 'empeche';
  for (const h of hotes) {
    if (h.nonReplacees.length > 0 || h.deplacees.length > 0 || h.nonVerifiables.length > 0) verdict = 'rouge';
    // Le canal qui dit l'effondrement quand le compte total n'a pas bougé
    // (« 17 portraits distincts à l'origine, 2 au vif »).
    if (h.distinctesApres < h.distinctesAvant) verdict = 'rouge';
  }
  // amendSet boucle sur les variantes : le rapport s'ACCUMULE, il ne s'écrase
  // pas. Un seul hôte rouge suffit à rendre l'ensemble rouge.
  if (!report.photos) {
    report.photos = {
      schemaVersion: 1,
      contractId: contractId || null,
      voieInstances: plan.info.voie,
      raisonVoie: plan.info.raison,
      accueilsParHote: plan.accueilsAttendus,
      hotes: [],
      verdict: 'vert',
      refusAvantMutation: null,
    };
  }
  for (const h of hotes) report.photos.hotes.push(h);
  if (verdict === 'rouge' || report.photos.verdict === 'rouge') report.photos.verdict = 'rouge';
  else if (verdict === 'empeche' || report.photos.verdict === 'empeche') report.photos.verdict = 'empeche';
  if (plan.accueilsAttendus > report.photos.accueilsParHote) report.photos.accueilsParHote = plan.accueilsAttendus;
}

async function amendSet(set, C) {
  set.setSharedPluginData('ds_contracts', 'contractId', C.contractId);
  const hash = specHash(C);
  if (set.getSharedPluginData('ds_contracts', 'specHash') === hash) {
    return { name: C.setName, skipped: true, reason: 'unchanged', nodeId: set.id, key: set.key };
  }
  const report = { name: C.setName, amended: true, nodeId: set.id, key: set.key,
    addedVariants: [], rebuiltVariants: 0, extraVariants: [], addedProps: [], editedDefaults: [] };
  // 016: the variant-name reconciliation must run BEFORE the first
  // componentPropertyDefinitions read — on a set already in the incomplete-
  // names error state, THAT read throws and the repair below would never be
  // reached (measured live: SectionHeader gaining Emphase+Alignement).
  // Sets gaining/losing the State preview axis reconcile by RENAME, not
  // duplication: an existing variant whose name matches an expected name
  // minus the ', State=Default' segment IS that variant (instances point at
  // it), so it is renamed in place — every variant node ID is preserved.
  // Main-file finding, 2026-07-08: name-only matching built 12 duplicates
  // and stranded the 12 originals as off-axis extras.
  const EV = withStateAxis(C);
  const expected = new Map(EV.map((v) => [v.name, v]));
  for (const ch of set.children) {
    if (expected.has(ch.name)) continue;
    const gained = ch.name + ', State=Default';
    const lost = ch.name.replace(', State=Default', '');
    if (expected.has(gained) && !set.children.some((o) => o.name === gained)) {
      ch.name = gained;
      report.renamedVariants = report.renamedVariants || [];
      report.renamedVariants.push(gained);
    } else if (lost !== ch.name && expected.has(lost) && !set.children.some((o) => o.name === lost)) {
      ch.name = lost;
      report.renamedVariants = report.renamedVariants || [];
      report.renamedVariants.push(lost);
    } else {
      // 016, generalization of the State-axis rename: a set gaining ANY new
      // VARIANT dimension leaves its old variants named without the new
      // segments ("Disposition=Standard" vs "Disposition=Standard, Emphase=…").
      // Complete the old name with each missing expected axis at its spec
      // default — the old node IS that variant (instances point at it). If
      // this amend already built a twin under the completed name, the twin is
      // ours and instance-free: remove it, keep the historied node. Measured
      // live (SectionHeader +Emphase+Alignement): the incomplete pair put the
      // whole set in "existing errors" and every composite read failed.
      const segsOf = (nom) => new Map(nom.split(',').map((seg) => seg.trim().split('=')).filter((kv) => kv.length === 2).map(([k, val]) => [k, val]));
      const parsed = segsOf(ch.name);
      // the canonical default combo is EV[0] (row 0 / col 0 by construction):
      // missing axes complete at THEIR spec default, in EV[0]'s axis order.
      const defauts = segsOf(EV[0].name);
      let completed = null;
      if (parsed.size > 0 && parsed.size < defauts.size && [...parsed].every(([k]) => defauts.has(k))) {
        completed = [...defauts.keys()].map((k) => k + '=' + (parsed.has(k) ? parsed.get(k) : defauts.get(k))).join(', ');
        if (!expected.has(completed)) completed = null;
      }
      if (completed && completed !== ch.name) {
        const twin = set.children.find((o) => o !== ch && o.name === completed);
        // 016 revue adversariale (finding 1) : ne JAMAIS remove le jumeau — sous
        // le nouvel ordre (rename avant build) un jumeau peut être un node
        // PRÉEXISTANT portant des instances (designer migration) ; le supprimer
        // orphelinerait ses instances irréversiblement. On le renomme hors du
        // namespace gouverné et on le SIGNALE — un humain arbitre.
        if (twin) {
          twin.name = completed + ' (doublon amend — à arbitrer)';
          report.mergedVariants = report.mergedVariants || [];
          report.mergedVariants.push(completed + ' [jumeau conservé, renommé]');
          report.extraVariants.push(twin.name);
        }
        ch.name = completed;
        report.renamedVariants = report.renamedVariants || [];
        report.renamedVariants.push(completed);
      } else {
        report.extraVariants.push(ch.name);
      }
    }
  }
  const defs = set.componentPropertyDefinitions;
  const newKeys = {};
  const defKey = (name) => newKeys[name] ||
    Object.keys(defs).find((k) => k.split('#')[0] === name) || null;

  for (const name of C.forwardedProps || []) {
    const k = defKey(name);
    if (k && defs[k]?.type === 'TEXT') {
      set.deleteComponentProperty(k);
      delete defs[k];
      report.removedForwardedProps = report.removedForwardedProps || [];
      report.removedForwardedProps.push(name);
    }
  }

  for (const w of [
    ...C.boolProps.map((bp) => ({ name: bp.property, type: 'BOOLEAN', def: bp.default })),
    ...(C.textProps || []).map((tp) => ({ name: tp.property, type: 'TEXT', def: tp.default })),
  ]) {
    const k = defKey(w.name);
    if (!k) { newKeys[w.name] = set.addComponentProperty(w.name, w.type, w.def); report.addedProps.push(w.name); }
    else if (defs[k].type === w.type && defs[k].defaultValue !== w.def) {
      set.editComponentProperty(k, { defaultValue: w.def });
      report.editedDefaults.push(w.name);
    }
  }
  for (const swap of C.swapProps || []) {
    const resolvedSwap = await iconSwapDefinition(swap);
    let k = defKey(swap.property);
    if (!k) {
      k = set.addComponentProperty(
        swap.property,
        'INSTANCE_SWAP',
        resolvedSwap.defaultId,
        { preferredValues: resolvedSwap.preferredValues },
      );
      newKeys[swap.property] = k;
      report.addedProps.push(swap.property);
    } else if (defs[k]?.type !== 'INSTANCE_SWAP') {
      throw new Error('Property type mismatch for governed icon swap: ' + swap.property);
    } else {
      const beforePreferred = JSON.stringify(defs[k].preferredValues || []);
      const afterPreferred = JSON.stringify(resolvedSwap.preferredValues);
      if (defs[k].defaultValue !== resolvedSwap.defaultId || beforePreferred !== afterPreferred) {
        set.editComponentProperty(k, {
          defaultValue: resolvedSwap.defaultId,
          preferredValues: resolvedSwap.preferredValues,
        });
        if (!report.editedDefaults.includes(swap.property)) report.editedDefaults.push(swap.property);
      }
    }
  }

  const existingByName = new Map(set.children.map((ch) => [ch.name, ch]));

  for (const v of EV) {
    let comp = existingByName.get(v.name);
    const registry = { texts: [], slots: [], visibles: [] };
    if (!comp) {
      comp = await buildNode(v.spec, registry);
      set.appendChild(comp);
      report.addedVariants.push(v.name);
    } else {
      // 017 — PRÉ-PASSE avant toute mutation : relever (maître ET instances de
      // page), compter les accueils, DÉCIDER. Une empreinte sans accueil jette
      // ICI, une ligne avant la première démolition (§X, FR-003a).
      const planPhotos = await preparerSauvetagePhotos(comp, [v.spec]);
      for (const child of [...comp.children]) child.remove();
      applyFrameSpec(comp, v.spec);
      for (const childSpec of v.spec.children || []) {
        const childNode = await buildNode(childSpec, registry);
        comp.appendChild(childNode);
        applyOverlay(comp, childNode, childSpec);
        if (childSpec.pct != null) {
          try { childNode.resize(Math.max(1, Math.round(comp.width * childSpec.pct)), childNode.height); childNode.primaryAxisSizingMode = 'FIXED'; } catch (e) {}
        }
        if (
          childSpec.type === 'frame' && (!childSpec.children || childSpec.children.length === 0) &&
          !childSpec.fixedHeight && !(childSpec.lits && childSpec.lits.height !== undefined) && !childSpec.shape
        ) {
          // #60 fix 4 (amend path): same empty-child declared default.
          try { childNode.layoutSizingVertical = 'FILL'; } catch (e) { /* parent not auto-layout */ }
        }
        if (childSpec.grow && 'layoutSizingHorizontal' in childNode) {
          try { childNode.layoutSizingHorizontal = 'FILL'; } catch (e) {}
        } else if (v.spec.layout && v.spec.layout.stretchChildren && !childSpec.fixedWidth && childSpec.type !== 'instance' && 'layoutSizingHorizontal' in childNode) {
          try { childNode.layoutSizingHorizontal = 'FILL'; } catch (e) {}
        }

        // 016 CSS text-flow (see buildNode): TEXT in a width-constrained
        // variant root fills and wraps.
        if (childNode.type === 'TEXT' && (childSpec.grow || v.spec.fixedWidth || (v.spec.layout && v.spec.layout.stretchChildren))) {
          try { childNode.textAutoResize = 'HEIGHT'; childNode.layoutSizingHorizontal = 'FILL'; } catch (e) {}
        }
    applyMarginBox(comp, childNode, childSpec);
      }
      restaurerPhotos(v.spec, comp, planPhotos, report, C.contractId);
      report.rebuiltVariants++;
    }
    for (const t of registry.texts) {
      let k = defKey(t.prop);
      if (!k) { k = set.addComponentProperty(t.prop, 'TEXT', t.default); newKeys[t.prop] = k; report.addedProps.push(t.prop); }
      else if (defs[k] && defs[k].defaultValue !== t.default && !report.editedDefaults.includes(t.prop)) {
        set.editComponentProperty(k, { defaultValue: t.default });
        report.editedDefaults.push(t.prop);
      }
      t.node.componentPropertyReferences = { ...(t.node.componentPropertyReferences || {}), characters: k };
    }
    for (const sl of registry.slots) {
      const util = await ensureSlotUtility();
      let k = defKey(sl.spec.slotProperty);
      if (!k) {
        const preferred = [];
        for (const depName of sl.spec.slotAccepts || []) {
          const target = findComponentByName(depName);
          preferred.push({ type: target.type === 'COMPONENT_SET' ? 'COMPONENT_SET' : 'COMPONENT', key: target.key });
        }
        k = set.addComponentProperty(sl.spec.slotProperty, 'INSTANCE_SWAP', sl.defaultId || util.id,
          preferred.length > 0 ? { preferredValues: preferred } : undefined);
        newKeys[sl.spec.slotProperty] = k;
        report.addedProps.push(sl.spec.slotProperty);
      }
      sl.instance.componentPropertyReferences = { ...(sl.instance.componentPropertyReferences || {}), mainComponent: k };
      if (sl.spec.slotOptional) {
        let vk = defKey('Show ' + sl.spec.slotProperty);
        if (!vk) { vk = set.addComponentProperty('Show ' + sl.spec.slotProperty, 'BOOLEAN', true); newKeys['Show ' + sl.spec.slotProperty] = vk; }
        sl.wrapper.componentPropertyReferences = { ...(sl.wrapper.componentPropertyReferences || {}), visible: vk };
      }
    }
    for (const vis of registry.visibles) {
      const k = defKey(vis.prop);
      if (!k) continue;
      vis.node.componentPropertyReferences = { ...(vis.node.componentPropertyReferences || {}), visible: k };
      vis.node.visible = vis.default;
    }
    for (const swap of C.swapProps || []) {
      const k = defKey(swap.property);
      if (!k) throw new Error('Governed icon swap property missing after amend: ' + swap.property);
      wireIconSwapNodes(registry, swap.property, k);
    }
    wireDepPropForwards(registry);
  }

  // Contract default combo must be the FIRST variant (Figma default = first).
  const first = set.children.find((ch) => ch.name === EV[0].name);
  if (first && set.children[0] !== first) set.insertChild(0, first);

  // Grid re-layout with the create path's math.
  const specByName = new Map(EV.map((sv) => [sv.name, sv]));
  const rowsN = Math.max(...EV.map((vv) => vv.row)) + 1;
  const colsN = Math.max(...EV.map((vv) => vv.col)) + 1;
  const colWs = new Array(colsN).fill(0);
  const rowHs = new Array(rowsN).fill(0);
  for (const child of set.children) {
    const sp = specByName.get(child.name);
    if (!sp) continue;
    colWs[sp.col] = Math.max(colWs[sp.col], child.width);
    rowHs[sp.row] = Math.max(rowHs[sp.row], child.height);
  }
  for (const child of set.children) {
    const sp = specByName.get(child.name);
    if (!sp) continue;
    let x = PAD, y = PAD;
    for (let i = 0; i < sp.col; i++) x += colWs[i] + PAD;
    for (let i = 0; i < sp.row; i++) y += rowHs[i] + PAD;
    child.x = x; child.y = y;
  }
  // B-3 finding 4: after re-gridding, the SET CONTAINER refits to the
  // children's extent + grid padding (the create path's exact math) —
  // without this, added variants/columns stayed clipped by stale bounds
  // (Banner's Focus column, Button's 220-cell grid, ProgressBar's height).
  // Extra (human-owned) variants may sit beyond the grid; never shrink
  // below their extent.
  {
    let totalW = colWs.reduce((a, b) => a + b, 0) + PAD * (colsN + 1);
    let totalH = rowHs.reduce((a, b) => a + b, 0) + PAD * (rowsN + 1);
    for (const child of set.children) {
      totalW = Math.max(totalW, child.x + child.width + PAD);
      totalH = Math.max(totalH, child.y + child.height + PAD);
    }
    set.resizeWithoutConstraints(totalW, totalH);
  }
  set.description = C.description;
  set.setSharedPluginData('ds_contracts', 'specHash', hash);
  return report;
}

// #60 fix 3: IN-PLACE AMEND for standalone COMPONENTs (non-set: Badge/Tag
// class) — the same identity-marker update semantics as amendSet: the
// component node (and key) instances bind to is preserved; the interior is
// contract-owned and rebuilt from spec; existing componentProperty IDs
// survive via defKey. Unchanged specs skip on the stored specHash.
async function amendComponent(comp, C) {
  comp.setSharedPluginData('ds_contracts', 'contractId', C.contractId);
  const hash = specHash(C);
  if (comp.getSharedPluginData('ds_contracts', 'specHash') === hash) {
    return { name: C.setName, skipped: true, reason: 'unchanged', nodeId: comp.id, key: comp.key };
  }
  const report = { name: C.setName, amended: true, standalone: true, nodeId: comp.id, key: comp.key, addedProps: [], editedDefaults: [] };
  const defs = comp.componentPropertyDefinitions;
  const newKeys = {};
  const defKey = (name) => newKeys[name] ||
    Object.keys(defs).find((k) => k.split('#')[0] === name) || null;
  for (const name of C.forwardedProps || []) {
    const k = defKey(name);
    if (k && defs[k]?.type === 'TEXT') {
      comp.deleteComponentProperty(k);
      delete defs[k];
      report.removedForwardedProps = report.removedForwardedProps || [];
      report.removedForwardedProps.push(name);
    }
  }
  for (const w of [
    ...C.boolProps.map((bp) => ({ name: bp.property, type: 'BOOLEAN', def: bp.default })),
    ...(C.textProps || []).map((tp) => ({ name: tp.property, type: 'TEXT', def: tp.default })),
  ]) {
    const k = defKey(w.name);
    if (!k) { newKeys[w.name] = comp.addComponentProperty(w.name, w.type, w.def); report.addedProps.push(w.name); }
    else if (defs[k].type === w.type && defs[k].defaultValue !== w.def) {
      comp.editComponentProperty(k, { defaultValue: w.def });
      report.editedDefaults.push(w.name);
    }
  }
  for (const swap of C.swapProps || []) {
    const resolvedSwap = await iconSwapDefinition(swap);
    let k = defKey(swap.property);
    if (!k) {
      k = comp.addComponentProperty(
        swap.property,
        'INSTANCE_SWAP',
        resolvedSwap.defaultId,
        { preferredValues: resolvedSwap.preferredValues },
      );
      newKeys[swap.property] = k;
      report.addedProps.push(swap.property);
    } else if (defs[k]?.type !== 'INSTANCE_SWAP') {
      throw new Error('Property type mismatch for governed icon swap: ' + swap.property);
    } else {
      const beforePreferred = JSON.stringify(defs[k].preferredValues || []);
      const afterPreferred = JSON.stringify(resolvedSwap.preferredValues);
      if (defs[k].defaultValue !== resolvedSwap.defaultId || beforePreferred !== afterPreferred) {
        comp.editComponentProperty(k, {
          defaultValue: resolvedSwap.defaultId,
          preferredValues: resolvedSwap.preferredValues,
        });
        if (!report.editedDefaults.includes(swap.property)) report.editedDefaults.push(swap.property);
      }
    }
  }
  const v = C.variants[0];
  const registry = { texts: [], slots: [], visibles: [] };
  // 017 — même PRÉ-PASSE que le chemin amendSet : relever le maître ET ses
  // instances de page, compter les accueils, DÉCIDER. Le refus tombe ici, une
  // ligne avant la première démolition (§X, FR-003a).
  const planPhotos = await preparerSauvetagePhotos(comp, [v.spec]);
  for (const child of [...comp.children]) child.remove();
  applyFrameSpec(comp, v.spec);
  for (const childSpec of v.spec.children || []) {
    const childNode = await buildNode(childSpec, registry);
    comp.appendChild(childNode);
    applyOverlay(comp, childNode, childSpec);
    if (childSpec.pct != null) {
      try { childNode.resize(Math.max(1, Math.round(comp.width * childSpec.pct)), childNode.height); childNode.primaryAxisSizingMode = 'FIXED'; } catch (e) {}
    }
    if (
      childSpec.type === 'frame' && (!childSpec.children || childSpec.children.length === 0) &&
      !childSpec.fixedHeight && !(childSpec.lits && childSpec.lits.height !== undefined) && !childSpec.shape
    ) {
      // #60 fix 4 (standalone amend path): same empty-child declared default.
      try { childNode.layoutSizingVertical = 'FILL'; } catch (e) { /* parent not auto-layout */ }
    }
    if (childSpec.grow && 'layoutSizingHorizontal' in childNode) {
      try { childNode.layoutSizingHorizontal = 'FILL'; } catch (e) {}
    } else if (v.spec.layout && v.spec.layout.stretchChildren && !childSpec.fixedWidth && childSpec.type !== 'instance' && 'layoutSizingHorizontal' in childNode) {
      try { childNode.layoutSizingHorizontal = 'FILL'; } catch (e) {}
    }

    // 016 CSS text-flow (see buildNode): TEXT in a width-constrained root
    // fills and wraps.
    if (childNode.type === 'TEXT' && (childSpec.grow || v.spec.fixedWidth || (v.spec.layout && v.spec.layout.stretchChildren))) {
      try { childNode.textAutoResize = 'HEIGHT'; childNode.layoutSizingHorizontal = 'FILL'; } catch (e) {}
    }
  }
  restaurerPhotos(v.spec, comp, planPhotos, report, C.contractId);
  for (const t of registry.texts) {
    let k = defKey(t.prop);
    if (!k) { k = comp.addComponentProperty(t.prop, 'TEXT', t.default); newKeys[t.prop] = k; report.addedProps.push(t.prop); }
    else if (defs[k] && defs[k].defaultValue !== t.default && !report.editedDefaults.includes(t.prop)) {
      comp.editComponentProperty(k, { defaultValue: t.default });
      report.editedDefaults.push(t.prop);
    }
    t.node.componentPropertyReferences = { ...(t.node.componentPropertyReferences || {}), characters: k };
  }
  for (const sl of registry.slots) {
    const util = await ensureSlotUtility();
    let k = defKey(sl.spec.slotProperty);
    if (!k) {
      const preferred = [];
      for (const depName of sl.spec.slotAccepts || []) {
        const target = findComponentByName(depName);
        preferred.push({ type: target.type === 'COMPONENT_SET' ? 'COMPONENT_SET' : 'COMPONENT', key: target.key });
      }
      k = comp.addComponentProperty(sl.spec.slotProperty, 'INSTANCE_SWAP', sl.defaultId || util.id,
        preferred.length > 0 ? { preferredValues: preferred } : undefined);
      newKeys[sl.spec.slotProperty] = k;
      report.addedProps.push(sl.spec.slotProperty);
    }
    sl.instance.componentPropertyReferences = { ...(sl.instance.componentPropertyReferences || {}), mainComponent: k };
    if (sl.spec.slotOptional) {
      let vk = defKey('Show ' + sl.spec.slotProperty);
      if (!vk) { vk = comp.addComponentProperty('Show ' + sl.spec.slotProperty, 'BOOLEAN', true); newKeys['Show ' + sl.spec.slotProperty] = vk; }
      sl.wrapper.componentPropertyReferences = { ...(sl.wrapper.componentPropertyReferences || {}), visible: vk };
    }
  }
  for (const vis of registry.visibles) {
    const k = defKey(vis.prop);
    if (!k) continue;
    vis.node.componentPropertyReferences = { ...(vis.node.componentPropertyReferences || {}), visible: k };
    vis.node.visible = vis.default;
  }
  for (const swap of C.swapProps || []) {
    const k = defKey(swap.property);
    if (!k) throw new Error('Governed icon swap property missing after amend: ' + swap.property);
    wireIconSwapNodes(registry, swap.property, k);
  }
  wireDepPropForwards(registry);
  comp.description = C.description;
  comp.setSharedPluginData('ds_contracts', 'specHash', hash);
  return report;
}

async function syncOne(C) {
  // Identity is the ds_contracts/contractId marker, NOT the set name — in a
  // brownfield file a name can belong to the host system's own component
  // (CBDS pilot: native 72-variant "Badge"). Legacy fallback: sets created
  // before the marker existed carry only specHash under the same namespace.
  let existing = null;
  for (const page of figma.root.children) {
    existing = page.findOne(
      (n) => (n.type === 'COMPONENT_SET' || n.type === 'COMPONENT') &&
        n.getSharedPluginData('ds_contracts', 'contractId') === C.contractId,
    );
    if (existing) break;
  }
  if (!existing) {
    for (const page of figma.root.children) {
      existing = page.findOne(
        (n) => (n.type === 'COMPONENT_SET' || n.type === 'COMPONENT') && n.name === C.setName &&
          n.getSharedPluginData('ds_contracts', 'specHash') !== '',
      );
      if (existing) break;
    }
  }
  // An anchored key is ours by definition — the contract records the key the
  // canvas minted. Covers legacy nodes that predate both plugin-data markers
  // (main-file finding, 2026-07-08: 17 standalone components duplicated).
  if (!existing && C.anchorKey) {
    for (const page of figma.root.children) {
      existing = page.findOne(
        (n) => (n.type === 'COMPONENT_SET' || n.type === 'COMPONENT') && n.key === C.anchorKey,
      );
      if (existing) break;
    }
    if (existing) existing.setSharedPluginData('ds_contracts', 'contractId', C.contractId);
  }
  if (existing && existing.type === 'COMPONENT_SET' && C.isSet) {
    return await amendSet(existing, C);
  }
  // #60 fix 3: standalone COMPONENTs (Badge/Tag class) amend in place too —
  // the "amend supports variant sets in v1" skip forced delete+recreate and
  // re-minted node ids/keys (Phase B-2 named finding 2).
  if (existing && existing.type === 'COMPONENT' && !C.isSet) {
    return await amendComponent(existing, C);
  }
  if (existing) {
    existing.setSharedPluginData('ds_contracts', 'contractId', C.contractId);
    return { name: C.setName, skipped: true, reason: 'set/standalone shape mismatch (' + existing.type + ' vs isSet=' + C.isSet + ') — a human retires the old node', nodeId: existing.id, key: existing.key };
  }

  // A same-named unmarked set is foreign: leave it alone, disambiguate ours.
  let displayName = C.setName;
  for (const page of figma.root.children) {
    const foreign = page.findOne(
      (n) => (n.type === 'COMPONENT_SET' || n.type === 'COMPONENT') && n.name === C.setName,
    );
    if (foreign) { displayName = C.setName + ' (' + C.contractId + ')'; break; }
  }

  // One page per component (see figma-sync/arrange.js for the file layout).
  let compPage = figma.root.children.find((p) => p.name === displayName);
  if (!compPage) { compPage = figma.createPage(); compPage.name = displayName; }

  const EV = withStateAxis(C);
  const built = [];
  for (const v of EV) {
    const registry = { texts: [], slots: [], visibles: [] };
    const comp = await buildNode(v.spec, registry);
    built.push({ v, comp, registry });
  }
  for (const b of built) {
    const propertyKeys = {};
    for (const t of b.registry.texts) {
      const key = b.comp.addComponentProperty(t.prop, 'TEXT', t.default);
      propertyKeys[t.prop] = key;
      t.node.componentPropertyReferences = { ...(t.node.componentPropertyReferences || {}), characters: key };
    }
    for (const s of b.registry.slots) {
      const util = await ensureSlotUtility();
      const preferred = [];
      for (const depName of s.spec.slotAccepts || []) {
        const target = findComponentByName(depName);
        preferred.push({
          type: target.type === 'COMPONENT_SET' ? 'COMPONENT_SET' : 'COMPONENT',
          key: target.key,
        });
      }
      const key = b.comp.addComponentProperty(
        s.spec.slotProperty,
        'INSTANCE_SWAP',
        s.defaultId || util.id,
        preferred.length > 0 ? { preferredValues: preferred } : undefined,
      );
      propertyKeys[s.spec.slotProperty] = key;
      s.instance.componentPropertyReferences = { ...(s.instance.componentPropertyReferences || {}), mainComponent: key };
      if (s.spec.slotOptional) {
        const vkey = b.comp.addComponentProperty('Show ' + s.spec.slotProperty, 'BOOLEAN', true);
        propertyKeys['Show ' + s.spec.slotProperty] = vkey;
        s.wrapper.componentPropertyReferences = { ...(s.wrapper.componentPropertyReferences || {}), visible: vkey };
      }
    }
    const boolKeys = {};
    for (const bp of C.boolProps) {
      boolKeys[bp.property] = b.comp.addComponentProperty(bp.property, 'BOOLEAN', bp.default);
      propertyKeys[bp.property] = boolKeys[bp.property];
    }
    for (const tp of C.textProps || []) {
      propertyKeys[tp.property] = b.comp.addComponentProperty(tp.property, 'TEXT', tp.default);
    }
    for (const swap of C.swapProps || []) {
      const resolvedSwap = await iconSwapDefinition(swap);
      const key = b.comp.addComponentProperty(
        swap.property,
        'INSTANCE_SWAP',
        resolvedSwap.defaultId,
        { preferredValues: resolvedSwap.preferredValues },
      );
      propertyKeys[swap.property] = key;
      wireIconSwapNodes(b.registry, swap.property, key);
    }
    for (const vis of b.registry.visibles) {
      const key = boolKeys[vis.prop];
      if (!key) continue;
      vis.node.componentPropertyReferences = { ...(vis.node.componentPropertyReferences || {}), visible: key };
      vis.node.visible = vis.default;
    }
    const defKey = (name) => propertyKeys[name] ||
      Object.keys(b.comp.componentPropertyDefinitions || {}).find((key) => key.split('#')[0] === name) || null;
    wireDepPropForwards(b.registry);
  }

  let target;
  if (C.isSet) {
    // combineAsVariants requires the nodes to already be ON the parent page.
    for (const b of built) compPage.appendChild(b.comp);
    target = figma.combineAsVariants(built.map((b) => b.comp), compPage);
    // Tight grid: rows = first axis, columns = second; per-track max sizing.
    const specByName = new Map(EV.map((s) => [s.name, s]));
    const rowsN = Math.max(...EV.map((v) => v.row)) + 1;
    const colsN = Math.max(...EV.map((v) => v.col)) + 1;
    const colWs = new Array(colsN).fill(0);
    const rowHs = new Array(rowsN).fill(0);
    for (const child of target.children) {
      const spec = specByName.get(child.name);
      if (!spec) continue;
      colWs[spec.col] = Math.max(colWs[spec.col], child.width);
      rowHs[spec.row] = Math.max(rowHs[spec.row], child.height);
    }
    for (const child of target.children) {
      const spec = specByName.get(child.name);
      if (!spec) continue;
      let x = PAD, y = PAD;
      for (let i = 0; i < spec.col; i++) x += colWs[i] + PAD;
      for (let i = 0; i < spec.row; i++) y += rowHs[i] + PAD;
      child.x = x;
      child.y = y;
    }
    const totalW = colWs.reduce((a, b) => a + b, 0) + PAD * (colsN + 1);
    const totalH = rowHs.reduce((a, b) => a + b, 0) + PAD * (rowsN + 1);
    target.resizeWithoutConstraints(totalW, totalH);
  } else {
    target = built[0].comp;
    compPage.appendChild(target);
  }
  target.name = displayName;
  target.description = C.description;
  target.x = 100;
  target.y = 100;
  target.setSharedPluginData('ds_contracts', 'specHash', specHash(C));
  target.setSharedPluginData('ds_contracts', 'contractId', C.contractId);

  return {
    name: C.setName,
    nodeId: target.id,
    key: target.key,
    variants: C.isSet ? target.children.length : 1,
    properties: Object.keys(target.componentPropertyDefinitions || {}),
  };
}

const results = [];
for (const C of COMPONENTS) {
  results.push(await syncOne(C));
}
return { createdNodeIds: results.filter((r) => !r.skipped).map((r) => r.nodeId), results, fontFallbacks };
